pub fn tag_datatype(mut tag: Str, mut ts: Tagofs) -> Str {
    loop {
        if null_p(ts) {
            return error(string_append(str_lit("kfx: not a datatype's tag: "), tag));
        } else {
            let tagcase_ = car(ts);
            match *tagcase_ {
                Tagof::Tagof(t, d) => {
                    if string_eq_p(t, tag) {
                        return d;
                    } else {
                        ts = cdr(ts);
                        continue;
                    }
                }
            }
        }
    }
}

