/// `<T, U>`, or with `bounded`, `<T: Copy + 'static, U: Copy + 'static>`
/// as every KFX value is; nothing for no names.
pub fn put_generics_of(names: Strings, bounded: bool, acc: Chars) -> Chars {
    if null_p(names) {
        acc
    } else {
        put(str_lit(">"), put_sep(lambda2(move |n: Str, acc: Chars| {
            let acc = put(camel(n), acc);
            if bounded {
                put(str_lit(": Copy + 'static"), acc)
            } else {
                acc
            }
        }), str_lit(", "), names, put(str_lit("<"), acc)))
    }
}

/// A module's datatypes, as the program names them, `m..d`, with their tags.
pub fn note_module_datatypes(mut m: Str, mut forms: Sexps, mut c: &'static Ctx) -> &'static Ctx {
    loop {
        if null_p(forms) {
            return c;
        } else if head_is_p(car(forms), str_lit("define-datatype")) {
            let d = string_append(m, string_append(str_lit(".."), type_head_name(second(items(car(forms))))));
            (forms, c) = (cdr(forms), {
                let tagcase_ = c;
                match *tagcase_ {
                    Ctx::Ctx(ds, ts, ks, ls, xs, fs, ms, es, mods) => {
                        ctx(cons(d, ds), note_tags(cdr(cdr(items(car(forms)))), d, ts), ks, ls, xs, fs, ms, es, mods)
                    }
                }
            });
            continue;
        } else {
            forms = cdr(forms);
            continue;
        }
    }
}

pub fn note(form: &'static Sexp, c: &'static Ctx) -> &'static Ctx {
    let tagcase_ = c;
    match *tagcase_ {
        Ctx::Ctx(ds, ts, ks, ls, xs, fs, ms, es, mods) => {
            if head_is_p(form, str_lit("define-datatype")) {
                let d = type_head_name(second(items(form)));
                ctx(cons(d, ds), note_tags(cdr(cdr(items(form))), d, ts), ks, ls, xs, fs, note_family(second(items(form)), true, ms), es, mods)
            } else if (head_is_p(form, str_lit("define-type")) || head_is_p(form, str_lit("define-generative"))) {
                ctx(ds, ts, ks, ls, xs, fs, note_family(second(items(form)), false, ms), es, mods)
            } else if head_is_p(form, str_lit("define-effect")) {
                ctx(ds, ts, ks, ls, xs, fs, ms, cons(typed(sym_name(second(items(form))), third(items(form))), es), mods)
            } else if module_def_p(form) {
                let m = sym_name(second(items(form)));
                note_module_datatypes(m, cdr(items(third(items(form)))), ctx(ds, ts, ks, ls, xs, fs, ms, es, cons(typed(m, third(items(form))), mods)))
            } else if (head_is_p(form, str_lit("define")) && (i64_eq(size(items(form)), 3i64) || i64_eq(size(items(form)), 4i64)) && not(procedure_p(last(items(form))))) {
                ctx(ds, ts, cons(sym_name(second(items(form))), ks), ls, xs, fs, ms, es, mods)
            } else {
                c
            }
        }
    }
}

pub fn collect(mut forms: Sexps, mut c: &'static Ctx) -> &'static Ctx {
    loop {
        if null_p(forms) {
            return c;
        } else {
            (forms, c) = (cdr(forms), note(car(forms), c));
            continue;
        }
    }
}

// Writing Rust
pub fn escape_char(c: char, q: char) -> Str {
    if char_eq_p(c, '\\') {
        str_lit("\\\\")
    } else if char_eq_p(c, q) {
        string_append(str_lit("\\"), char_to_string(c))
    } else if char_eq_p(c, '\n') {
        str_lit("\\n")
    } else if char_eq_p(c, '\t') {
        str_lit("\\t")
    } else {
        char_to_string(c)
    }
}

/// `cs` as the inside of a Rust literal delimited by `q`.
pub fn put_escaped(mut cs: Chars, mut q: char, mut acc: Chars) -> Chars {
    loop {
        if null_p(cs) {
            return acc;
        } else {
            (cs, acc) = (cdr(cs), put(escape_char(car(cs), q), acc));
            continue;
        }
    }
}

pub fn dotted_from(mut seen: Chars, mut cs: Chars) -> Strings {
    loop {
        if (null_p(cs) || null_p(cdr(cs))) {
            return nil();
        } else if (char_eq_p(car(cs), '.') && char_eq_p(car(cdr(cs)), '.')) {
            return the::<Strings>(cons(rev_to_string(seen), cons(list_to_string(cdr(cdr(cs))), nil())));
        } else {
            (seen, cs) = (cons(car(cs), seen), cdr(cs));
            continue;
        }
    }
}

/// A module's type as the program names it, `m..t`: `m` and `t`; else none.
pub fn dotted(s: Str) -> Strings {
    dotted_from(nil(), string_chars(s))
}

/// Module `m`'s type `t`, from outside it: a datatype's a reference.
pub fn type_path(c: &'static Ctx, m: Str, t: Str) -> Str {
    string_append(if string_member_p(string_append(m, string_append(str_lit(".."), t)), ctx_datatypes(c)) {
        str_lit("&'static ")
    } else {
        str_lit("")
    }, string_append(mangle(m), string_append(str_lit("::"), camel(t))))
}

/// A datatype's enum, a module's named by its path.
pub fn datatype_path(d: Str) -> Str {
    if null_p(dotted(d)) {
        camel(d)
    } else {
        string_append(mangle(car(dotted(d))), string_append(str_lit("::"), camel(car(cdr(dotted(d))))))
    }
}

/// A type. A name that is no base type or datatype is a type abbreviation
/// or a type variable, either way a Rust type of the same name.
pub fn put_type(c: &'static Ctx, t: &'static Sexp, acc: Chars) -> Chars {
    let tagcase_ = t;
    match *tagcase_ {
        Sexp::Sym(s) => {
            if string_eq_p(s, str_lit("i64")) {
                put(str_lit("i64"), acc)
            } else if string_eq_p(s, str_lit("int")) {
                put(str_lit("Int"), acc)
            } else if string_eq_p(s, str_lit("nat")) {
                put(str_lit("Int"), acc)
            } else if string_eq_p(s, str_lit("f64")) {
                put(str_lit("f64"), acc)
            } else if string_eq_p(s, str_lit("bool")) {
                put(str_lit("bool"), acc)
            } else if string_eq_p(s, str_lit("char")) {
                put(str_lit("char"), acc)
            } else if string_eq_p(s, str_lit("unit")) {
                put(str_lit("()"), acc)
            } else if string_eq_p(s, str_lit("void")) {
                put(str_lit("!"), acc)
            } else if string_eq_p(s, str_lit("string")) {
                put(str_lit("Str"), acc)
            } else if not(null_p(dotted(s))) {
                put(type_path(c, car(dotted(s)), car(cdr(dotted(s)))), acc)
            } else if string_member_p(s, ctx_datatypes(c)) {
                put(camel(s), put(str_lit("&'static "), acc))
            } else if not(string_eq_p(opener(string_append(str_lit("%type "), s), ctx_locals(c)), str_lit(""))) {
                put(type_path(c, opener(string_append(str_lit("%type "), s), ctx_locals(c)), s), acc)
            } else {
                put(camel(s), acc)
            }
        }
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            if sym_is_p(car(xs), str_lit("listof")) {
                put(str_lit(">"), put_type(c, second(xs), put(str_lit("List<"), acc)))
            } else if sym_is_p(car(xs), str_lit("flatarrayof")) {
                put(str_lit(">"), put_type(c, second(xs), put(str_lit("FlatArray<"), acc)))
            } else if sym_is_p(car(xs), str_lit("ref")) {
                put(str_lit(">"), put_type(c, second(xs), put(str_lit("Ref<"), acc)))
            } else if sym_is_p(car(xs), str_lit("subr")) {
                let acc = put(str_lit("&'static dyn Fn("), acc);
                let acc = put_types(c, items(third(xs)), acc);
                let acc = put(str_lit(") -> "), acc);
                if fallible_effect_p(c, second(xs)) {
                    put(str_lit(", Unwind>"), put_type(c, fourth(xs), put(str_lit("Result<"), acc)))
                } else {
                    put_type(c, fourth(xs), acc)
                }
            } else if sym_is_p(car(xs), str_lit("prompt-tag")) {
                put(str_lit(">"), put_type(c, third(xs), put(str_lit(", "), put_type(c, second(xs), put(str_lit("Tag<"), acc)))))
            } else if sym_is_p(car(xs), str_lit("select")) {
                put(type_path(c, sym_name(second(xs)), sym_name(third(xs))), acc)
            } else if sym_is_p(car(xs), str_lit("poly")) {
                error(str_lit("kfx: a poly type is only a definition's, at its top"))
            } else if {
                let tagcase_ = car(xs);
                match *tagcase_ {
                    Sexp::Sym(n) => {
                        not(null_p(find_family_of(c, n)))
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            } {
                let tagcase_ = car(find_family_of(c, sym_name(car(xs))));
                match *tagcase_ {
                    Family::Family(n, datatype, kinds) => {
                        let acc = if datatype {
                            put(str_lit("&'static "), acc)
                        } else {
                            acc
                        };
                        let acc = put(camel(n), acc);
                        let args = type_arguments(cdr(xs), kinds);
                        if null_p(args) {
                            acc
                        } else {
                            put(str_lit(">"), put_types(c, args, put(str_lit("<"), acc)))
                        }
                    }
                }
            } else {
                error(str_lit("kfx: a type KFX-0 does not have"))
            }
        }
        _ => {
            let other = tagcase_;
            error(str_lit("kfx: a type KFX-0 does not have"))
        }
    }
}

/// A family's arguments for its parameters of kind `type`: the others,
/// regions, are erased.
pub fn type_arguments(mut args: Sexps, mut kinds: Strings) -> Sexps {
    loop {
        if (null_p(args) || null_p(kinds)) {
            return nil();
        } else if string_eq_p(car(kinds), str_lit("type")) {
            return cons(car(args), type_arguments(cdr(args), cdr(kinds)));
        } else {
            (args, kinds) = (cdr(args), cdr(kinds));
            continue;
        }
    }
}

/// Types, separated by commas.
pub fn put_types(c: &'static Ctx, types: Sexps, acc: Chars) -> Chars {
    put_sep(lambda2(move |t: &'static Sexp, acc| {
        put_type(c, t, acc)
    }), str_lit(", "), types, acc)
}

/// What `s` is where it is named: `local`, `knot` (a procedure of a
/// `letrec`, in its group's lambdas, before it is made: reached through
/// its knot), or `` (not bound locally). The innermost binding counts.
pub fn local_kind(mut s: Str, mut ls: Strings) -> Str {
    loop {
        if null_p(ls) {
            return str_lit("");
        } else if string_eq_p(car(ls), s) {
            return str_lit("local");
        } else if string_eq_p(car(ls), string_append(str_lit("%knot "), s)) {
            return str_lit("knot");
        } else if string_eq_p(car(ls), string_append(str_lit("%item "), s)) {
            return str_lit("item");
        } else {
            ls = cdr(ls);
            continue;
        }
    }
}

/// A module's value, named in a `with`: `m::x`, called if a constant.
pub fn item_path(c: &'static Ctx, s: Str) -> Str {
    let m = opener(string_append(str_lit("%item "), s), ctx_locals(c));
    string_append(mangle(m), string_append(str_lit("::"), string_append(mangle(s), if string_member_p(s, item_constants(module_items(c, m))) {
        str_lit("()")
    } else {
        str_lit("")
    })))
}

/// Whether the function or closure being written returns a `Result`.
pub fn fallible_here_p(c: &'static Ctx) -> bool {
    string_eq_p(local_kind(str_lit("%fallible"), ctx_locals(c)), str_lit("local"))
}

/// A call's operator: a knot's procedure, a constant's value (a
/// procedure a definition made, not a lambda), or a name.
pub fn callee(c: &'static Ctx, h: Str) -> Str {
    let kind = local_kind(h, ctx_locals(c));
    if string_eq_p(kind, str_lit("knot")) {
        string_append(str_lit("("), string_append(mangle(h), str_lit("__knot.get())")))
    } else if string_eq_p(kind, str_lit("item")) {
        item_path(c, h)
    } else if (string_eq_p(kind, str_lit("")) && string_member_p(h, ctx_constants(c))) {
        string_append(mangle(h), str_lit("()"))
    } else {
        mangle(h)
    }
}

pub fn put_var(c: &'static Ctx, s: Str, acc: Chars) -> Chars {
    if string_eq_p(s, str_lit("#t")) {
        put(str_lit("true"), acc)
    } else if string_eq_p(s, str_lit("#f")) {
        put(str_lit("false"), acc)
    } else if string_eq_p(s, str_lit("#u")) {
        put(str_lit("()"), acc)
    } else if string_eq_p(local_kind(s, ctx_locals(c)), str_lit("knot")) {
        put(str_lit(".get()"), put(str_lit("__knot"), put(mangle(s), acc)))
    } else if string_eq_p(local_kind(s, ctx_locals(c)), str_lit("local")) {
        put(mangle(s), acc)
    } else if string_eq_p(local_kind(s, ctx_locals(c)), str_lit("item")) {
        let m = opener(string_append(str_lit("%item "), s), ctx_locals(c));
        put(item_path(c, s), if string_member_p(s, item_constants(module_items(c, m))) {
            acc
        } else {
            put(str_lit("&"), acc)
        })
    } else if (string_eq_p(s, str_lit("nil")) || string_member_p(s, ctx_constants(c))) {
        put(str_lit("()"), put(mangle(s), acc))
    } else {
        put(mangle(s), put(str_lit("&"), acc))
    }
}

pub fn put_spaces(mut k: i64, mut acc: Chars) -> Chars {
    loop {
        if i64_eq(k, 0i64) {
            return acc;
        } else {
            (k, acc) = (i64_minus(k, 1i64), put(str_lit("    "), acc));
            continue;
        }
    }
}

/// A new line, indented `n` levels.
pub fn put_nl(n: i64, acc: Chars) -> Chars {
    put_spaces(n, put(str_lit("\n"), acc))
}

/// A string literal where a body's value is not taken is a comment: KFX's
/// comments are strings, since `;` comments do not survive reading. Each of
/// its lines is written after `prefix` (`//` or `///`), leading spaces
/// dropped; `fresh` says no prefix has been written for this line yet.
pub fn put_comment(mut cs: Chars, mut prefix: Str, mut n: i64, mut fresh: bool, mut acc: Chars) -> Chars {
    loop {
        if null_p(cs) {
            return acc;
        } else if char_eq_p(car(cs), '\n') {
            (cs, fresh, acc) = (cdr(cs), true, put_nl(n, if fresh {
                put(prefix, acc)
            } else {
                acc
            }));
            continue;
        } else if (fresh && char_eq_p(car(cs), ' ')) {
            (cs, fresh) = (cdr(cs), true);
            continue;
        } else if fresh {
            (cs, fresh, acc) = (cdr(cs), false, cons(car(cs), put(str_lit(" "), put(prefix, acc))));
            continue;
        } else {
            (cs, fresh, acc) = (cdr(cs), false, cons(car(cs), acc));
            continue;
        }
    }
}

pub fn comment_p(e: &'static Sexp) -> bool {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Str(s) => {
            true
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

pub fn comment_text(e: &'static Sexp) -> Str {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Str(s) => {
            s
        }
        _ => {
            let other = tagcase_;
            str_lit("")
        }
    }
}

/// Names, separated by commas.
pub fn put_names(xs: Sexps, acc: Chars) -> Chars {
    put_sep(lambda2(move |x: &'static Sexp, acc| {
        put(mangle(sym_name(x)), acc)
    }), str_lit(", "), xs, acc)
}

// Self tail calls. Rust has no tail calls, so a procedure that calls itself
// last is a `loop`: the call assigns its parameters and `continue`s, and
// everything else it could end with is `return`ed.
pub enum Tail {
    Value(),
    Returns(Str, Strings, bool, bool),
    OkValue(),
}

pub fn value() -> &'static Tail {
    alloc(Tail::Value())
}

pub fn returns(f0: Str, f1: Strings, f2: bool, f3: bool) -> &'static Tail {
    alloc(Tail::Returns(f0, f1, f2, f3))
}

pub fn ok_value() -> &'static Tail {
    alloc(Tail::OkValue())
}

// `value`: an expression whose value is used. `returns`: the last thing a
// looping procedure does, with the procedure's name and parameters; the
// flag is false where a binding hides a parameter, since an assignment
// would then reach the binding, not the parameter.
pub fn binding_name(binding: &'static Sexp) -> Str {
    sym_name(car(items(binding)))
}

/// `t`, under bindings of `names`.
pub fn hide(t: &'static Tail, names: Strings) -> &'static Tail {
    let tagcase_ = t;
    match *tagcase_ {
        Tail::Returns(f, ps, live, ok) => {
            if (live && any_p(lambda1(move |x: Str| {
                string_member_p(x, ps)
            }), names)) {
                returns(f, ps, false, ok)
            } else {
                t
            }
        }
        _ => {
            let other = tagcase_;
            t
        }
    }
}

pub fn ok_value_p(t: &'static Tail) -> bool {
    let tagcase_ = t;
    match *tagcase_ {
        Tail::OkValue() => {
            true
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

pub fn returns_ok_p(t: &'static Tail) -> bool {
    let tagcase_ = t;
    match *tagcase_ {
        Tail::Returns(f, ps, live, ok) => {
            ok
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

pub fn returns_p(t: &'static Tail) -> bool {
    let tagcase_ = t;
    match *tagcase_ {
        Tail::Returns(f, ps, live, ok) => {
            true
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// An abort: `return Err(...)` in Rust, so no value to return or wrap.
pub fn abort_p(c: &'static Ctx, e: &'static Sexp) -> bool {
    (head_is_p(e, str_lit("abort-current-continuation")) && string_eq_p(local_kind(str_lit("abort-current-continuation"), ctx_locals(c)), str_lit("")))
}

pub fn self_call_p(t: &'static Tail, e: &'static Sexp) -> bool {
    let tagcase_ = t;
    match *tagcase_ {
        Tail::Returns(f, ps, live, ok) => {
            (live && head_is_p(e, f) && i64_eq(size(cdr(items(e))), size(ps)))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// The forms whose last parts stand where they do.
pub fn control_p(e: &'static Sexp) -> bool {
    (head_is_p(e, str_lit("if")) || head_is_p(e, str_lit("cond")) || head_is_p(e, str_lit("case")) || head_is_p(e, str_lit("tagcase")) || head_is_p(e, str_lit("let")) || head_is_p(e, str_lit("let*")) || head_is_p(e, str_lit("begin")) || head_is_p(e, str_lit("letrec")) || head_is_p(e, str_lit("letregion")) || head_is_p(e, str_lit("with")))
}

/// `c` in `(with m ...)`: `m`'s values and types, hiding what is outside.
pub fn with_opened(c: &'static Ctx, e: &'static Sexp) -> &'static Ctx {
    let m = sym_name(second(items(e)));
    let forms = module_items(c, m);
    with_locals(c, cons(string_append(str_lit("%with "), m), onto(map(lambda1(move |x: Str| {
        string_append(str_lit("%type "), x)
    }), item_types(forms)), map(lambda1(move |x: Str| {
        string_append(str_lit("%item "), x)
    }), item_values(forms)))))
}

/// `t` in `(with m ...)`: a procedure `m` gives, named as the one written,
/// is not it, and a parameter `m` hides is not to be assigned.
pub fn opened_tail(c: &'static Ctx, e: &'static Sexp, t: &'static Tail) -> &'static Tail {
    let names = item_values(module_items(c, sym_name(second(items(e)))));
    let tagcase_ = t;
    match *tagcase_ {
        Tail::Returns(f, ps, live, ok) => {
            if string_member_p(f, names) {
                returns(f, ps, false, ok)
            } else {
                hide(t, names)
            }
        }
        _ => {
            let other = tagcase_;
            t
        }
    }
}

/// Whether `e`, standing at `t`, makes a self tail call: whether its
/// procedure loops.
pub fn tail_calls_p(mut t: &'static Tail, mut e: &'static Sexp) -> bool {
    loop {
        if self_call_p(t, e) {
            return true;
        } else if head_is_p(e, str_lit("if")) {
            let xs = cdr(items(e));
            return (tail_calls_p(t, second(xs)) || tail_calls_p(t, third(xs)));
        } else if head_is_p(e, str_lit("cond")) {
            return arms_tail_calls_p(t, cdr(items(e)));
        } else if head_is_p(e, str_lit("case")) {
            return arms_tail_calls_p(t, cdr(cdr(items(e))));
        } else if head_is_p(e, str_lit("tagcase")) {
            return tag_arms_tail_calls_p(t, cdr(cdr(items(e))));
        } else if (head_is_p(e, str_lit("let")) || head_is_p(e, str_lit("let*")) || head_is_p(e, str_lit("letrec"))) {
            let xs = cdr(items(e));
            (t, e) = (hide(t, map(&binding_name, items(car(xs)))), last(cdr(xs)));
            continue;
        } else if head_is_p(e, str_lit("begin")) {
            e = last(cdr(items(e)));
            continue;
        } else if head_is_p(e, str_lit("letregion")) {
            e = last(cdr(cdr(items(e))));
            continue;
        } else {
            return false;
        }
    }
}

/// A `cond`'s clauses, or a `case`'s arms: each a test or data, then a body.
pub fn arms_tail_calls_p(mut t: &'static Tail, mut arms: Sexps) -> bool {
    loop {
        if null_p(arms) {
            return false;
        } else if tail_calls_p(t, last(cdr(items(car(arms))))) {
            return true;
        } else {
            arms = cdr(arms);
            continue;
        }
    }
}

pub fn tag_arms_tail_calls_p(t: &'static Tail, arms: Sexps) -> bool {
    if null_p(arms) {
        false
    } else {
        let arm = items(car(arms));
        let bound = if sym_is_p(car(arm), str_lit("else")) {
            the::<Strings>(cons(sym_name(second(arm)), nil()))
        } else {
            map(&sym_name, items(second(arm)))
        };
        (tail_calls_p(hide(t, bound), last(cdr(cdr(arm)))) || tag_arms_tail_calls_p(t, cdr(arms)))
    }
}

pub enum Assign {
    Assign(Strings, Sexps),
}

pub fn assign(f0: Strings, f1: Sexps) -> &'static Assign {
    alloc(Assign::Assign(f0, f1))
}

/// The parameters a self tail call changes, and their new values: an
/// argument that is the parameter itself changes nothing.
pub fn changes(ps: Strings, args: Sexps) -> &'static Assign {
    if null_p(ps) {
        assign(nil(), nil())
    } else {
        let tagcase_ = changes(cdr(ps), cdr(args));
        match *tagcase_ {
            Assign::Assign(names, values) => {
                if sym_is_p(car(args), car(ps)) {
                    assign(names, values)
                } else {
                    assign(cons(car(ps), names), cons(car(args), values))
                }
            }
        }
    }
}

/// Names, mangled, separated by commas.
pub fn put_strings(xs: Strings, acc: Chars) -> Chars {
    put_sep(lambda2(move |x: Str, acc| {
        put(mangle(x), acc)
    }), str_lit(", "), xs, acc)
}

// Every writer of an expression takes `n`, the indentation of the line it
// starts on, and `t`, where the expression stands.
pub fn put_exp(c: &'static Ctx, e: &'static Sexp, n: i64, t: &'static Tail, acc: Chars) -> Chars {
    if self_call_p(t, e) {
        put_continue(c, cdr(items(e)), n, t, acc)
    } else if (returns_p(t) && abort_p(c, e)) {
        put(str_lit(";"), put_exp(c, e, n, value(), acc))
    } else if (returns_p(t) && not(control_p(e))) {
        if returns_ok_p(t) {
            put(str_lit(");"), put_exp(c, e, n, value(), put(str_lit("return Ok("), acc)))
        } else {
            put(str_lit(";"), put_exp(c, e, n, value(), put(str_lit("return "), acc)))
        }
    } else if (ok_value_p(t) && not(control_p(e)) && not(abort_p(c, e))) {
        put(str_lit(")"), put_exp(c, e, n, value(), put(str_lit("Ok("), acc)))
    } else {
        let tagcase_ = e;
        match *tagcase_ {
            Sexp::Num(k, num_file, num_pos) => {
                if ctx_fact_p(c, num_file, num_pos, str_lit("int")) {
                    put(str_lit(")"), put(i64_to_string(k), put(str_lit("int_lit("), acc)))
                } else {
                    put(str_lit("i64"), put(i64_to_string(k), acc))
                }
            }
            Sexp::Chr(ch) => {
                put(str_lit("'"), put_escaped(cons(ch, nil()), '\'', put(str_lit("'"), acc)))
            }
            Sexp::Real(x) => {
                // As Rust writes a double: a digit after the point (`1.` is `1.0`).
                put(str_lit("f64"), if char_eq_p(last(string_chars(x)), '.') {
                    put(str_lit("0"), put(x, acc))
                } else {
                    put(x, acc)
                })
            }
            Sexp::Str(s) => {
                put(str_lit("\")"), put_escaped(string_chars(s), '"', put(str_lit("str_lit(\""), acc)))
            }
            Sexp::Sym(s) => {
                put_var(c, s, acc)
            }
            Sexp::Lst(xs, src_file, src_line, src_pos) => {
                let tagcase_ = car(xs);
                match *tagcase_ {
                    Sexp::Sym(h) => {
                        put_form(c, e, h, cdr(xs), n, t, acc)
                    }
                    _ => {
                        let head = tagcase_;
                        let acc = put(str_lit("("), acc);
                        let acc = put_exp(c, head, n, value(), acc);
                        let acc = put(str_lit(")("), acc);
                        put(str_lit(")"), if null_p(cdr(xs)) {
                            acc
                        } else {
                            put_joined(c, cdr(xs), str_lit(", "), n, acc)
                        })
                    }
                }
            }
        }
    }
}

/// A self tail call: the parameters it changes assigned, all at once.
pub fn put_continue(c: &'static Ctx, args: Sexps, n: i64, t: &'static Tail, acc: Chars) -> Chars {
    let tagcase_ = t;
    match *tagcase_ {
        Tail::Returns(f, ps, live, ok) => {
            let tagcase_ = changes(ps, args);
            match *tagcase_ {
                Assign::Assign(names, values) => {
                    let acc = if null_p(names) {
                        acc
                    } else if null_p(cdr(names)) {
                        let acc = put(mangle(car(names)), acc);
                        let acc = put(str_lit(" = "), acc);
                        let acc = put_exp(c, car(values), n, value(), acc);
                        put_nl(n, put(str_lit(";"), acc))
                    } else {
                        let acc = put(str_lit("("), acc);
                        let acc = put_strings(names, acc);
                        let acc = put(str_lit(") = ("), acc);
                        let acc = put_joined(c, values, str_lit(", "), n, acc);
                        put_nl(n, put(str_lit(");"), acc))
                    };
                    put(str_lit("continue;"), acc)
                }
            }
        }
        _ => {
            let other = tagcase_;
            error(str_lit("kfx: a self tail call where no procedure loops"))
        }
    }
}

/// Expressions separated by `sep`.
pub fn put_joined(c: &'static Ctx, xs: Sexps, sep: Str, n: i64, acc: Chars) -> Chars {
    put_sep(lambda2(move |x: &'static Sexp, acc| {
        put_exp(c, x, n, value(), acc)
    }), sep, xs, acc)
}

/// A body as the inside of a block: each expression on a line of its own,
/// the last standing at `t`. A last `let`, `let*`, `begin` or `tagcase`
/// is written into the block rather than as a block of its own.
pub fn put_stmts(mut c: &'static Ctx, mut es: Sexps, mut n: i64, mut t: &'static Tail, mut acc: Chars) -> Chars {
    loop {
        let e = car(es);
        if not(null_p(cdr(es))) {
            let acc = if comment_p(e) {
                put_comment(string_chars(comment_text(e)), str_lit("//"), n, true, acc)
            } else {
                put(str_lit(";"), put_exp(c, e, n, value(), acc))
            };
            return put_stmts(c, cdr(es), n, t, put_nl(n, acc));
        } else if (head_is_p(e, str_lit("let")) || head_is_p(e, str_lit("let*"))) {
            let xs = cdr(items(e));
            let names = map(&binding_name, items(car(xs)));
            (c, es, t, acc) = (with_locals(c, names), cdr(xs), hide(t, names), if head_is_p(e, str_lit("let")) {
                put_let(c, items(car(xs)), n, acc)
            } else {
                put_let_star(c, items(car(xs)), n, acc)
            });
            continue;
        } else if head_is_p(e, str_lit("begin")) {
            es = cdr(items(e));
            continue;
        } else if head_is_p(e, str_lit("letregion")) {
            es = cdr(cdr(items(e)));
            continue;
        } else if head_is_p(e, str_lit("with")) {
            (c, es, t) = (with_opened(c, e), cdr(cdr(items(e))), opened_tail(c, e, t));
            continue;
        } else if head_is_p(e, str_lit("letrec")) {
            let xs = cdr(items(e));
            let bindings = items(car(xs));
            let names = map(&binding_name, bindings);
            (c, es, t, acc) = (with_locals(c, names), cdr(xs), hide(t, names), put_letrec(c, bindings, names, n, acc));
            continue;
        } else if head_is_p(e, str_lit("tagcase")) {
            return put_tagcase(c, cdr(items(e)), n, t, acc);
        } else {
            return put_exp(c, e, n, t, acc);
        }
    }
}

pub fn put_block(c: &'static Ctx, es: Sexps, n: i64, t: &'static Tail, acc: Chars) -> Chars {
    let acc = put_nl(i64_plus(n, 1i64), put(str_lit("{"), acc));
    let acc = put_stmts(c, es, i64_plus(n, 1i64), t, acc);
    put(str_lit("}"), put_nl(n, acc))
}

pub fn put_cond(c: &'static Ctx, clauses: Sexps, n: i64, t: &'static Tail, acc: Chars) -> Chars {
    let clause = items(car(clauses));
    if sym_is_p(car(clause), str_lit("else")) {
        put_block(c, cdr(clause), n, t, acc)
    } else {
        let acc = put(str_lit("if "), acc);
        let acc = put_exp(c, car(clause), n, value(), acc);
        let acc = put(str_lit(" "), acc);
        let acc = put_block(c, cdr(clause), n, t, acc);
        let acc = put(str_lit(" else "), acc);
        put_cond(c, cdr(clauses), n, t, acc)
    }
}

pub fn put_let1(c: &'static Ctx, binding: &'static Sexp, n: i64, acc: Chars) -> Chars {
    let acc = put(str_lit("let "), acc);
    let acc = put(mangle(sym_name(car(items(binding)))), acc);
    let acc = put(str_lit(" = "), acc);
    let acc = put_exp(c, second(items(binding)), n, value(), acc);
    put_nl(n, put(str_lit(";"), acc))
}

/// Each binding sees those before it.
pub fn put_let_star(mut c: &'static Ctx, mut bindings: Sexps, mut n: i64, mut acc: Chars) -> Chars {
    loop {
        if null_p(bindings) {
            return acc;
        } else {
            (c, bindings, acc) = (with_locals(c, map(&binding_name, cons(car(bindings), nil()))), cdr(bindings), put_let1(c, car(bindings), n, acc));
            continue;
        }
    }
}

pub fn put_binding_values(c: &'static Ctx, bindings: Sexps, n: i64, acc: Chars) -> Chars {
    let acc = put_exp(c, second(items(car(bindings))), n, value(), acc);
    if null_p(cdr(bindings)) {
        acc
    } else {
        put_binding_values(c, cdr(bindings), n, put(str_lit(", "), acc))
    }
}

pub fn put_binding_names(bindings: Sexps, acc: Chars) -> Chars {
    let acc = put(mangle(sym_name(car(items(car(bindings))))), acc);
    if null_p(cdr(bindings)) {
        acc
    } else {
        put_binding_names(cdr(bindings), put(str_lit(", "), acc))
    }
}

/// `let` binds in parallel: more than one binding is a tuple.
pub fn put_let(c: &'static Ctx, bindings: Sexps, n: i64, acc: Chars) -> Chars {
    if null_p(bindings) {
        acc
    } else if null_p(cdr(bindings)) {
        put_let1(c, car(bindings), n, acc)
    } else {
        let acc = put(str_lit("let ("), acc);
        let acc = put_binding_names(bindings, acc);
        let acc = put(str_lit(") = ("), acc);
        let acc = put_binding_values(c, bindings, n, acc);
        put_nl(n, put(str_lit(");"), acc))
    }
}

pub fn put_case_arms(c: &'static Ctx, arms: Sexps, n: i64, t: &'static Tail, acc: Chars) -> Chars {
    if null_p(arms) {
        acc
    } else {
        let arm = items(car(arms));
        let acc = put_nl(n, acc);
        let acc = if sym_is_p(car(arm), str_lit("else")) {
            put(str_lit("_"), acc)
        } else {
            put_joined(c, items(car(arm)), str_lit(" | "), n, acc)
        };
        let acc = put(str_lit(" => "), acc);
        let acc = put_block(c, cdr(arm), n, t, acc);
        put_case_arms(c, cdr(arms), n, t, acc)
    }
}

pub fn put_tagcase_arms(c: &'static Ctx, arms: Sexps, n: i64, t: &'static Tail, acc: Chars) -> Chars {
    if null_p(arms) {
        acc
    } else {
        let arm = items(car(arms));
        let tag = sym_name(car(arm));
        let else_p = string_eq_p(tag, str_lit("else"));
        let bound = if else_p {
            the::<Strings>(cons(sym_name(second(arm)), nil()))
        } else {
            map(&sym_name, items(second(arm)))
        };
        let acc = put_nl(n, acc);
        let acc = if else_p {
            let acc = put(str_lit("_ => {"), acc);
            let acc = put_nl(i64_plus(n, 1i64), acc);
            let acc = put(str_lit("let "), acc);
            let acc = put(mangle(sym_name(second(arm))), acc);
            put_nl(i64_plus(n, 1i64), put(str_lit(" = tagcase_;"), acc))
        } else {
            let acc = put(datatype_path(tag_datatype(tag, ctx_tags(c))), acc);
            let acc = put(str_lit("::"), acc);
            let acc = put(camel(tag), acc);
            let acc = put(str_lit("("), acc);
            let acc = put_names(items(second(arm)), acc);
            put_nl(i64_plus(n, 1i64), put(str_lit(") => {"), acc))
        };
        let acc = put_stmts(with_locals(c, bound), cdr(cdr(arm)), i64_plus(n, 1i64), hide(t, bound), acc);
        let acc = put(str_lit("}"), put_nl(n, acc));
        put_tagcase_arms(c, cdr(arms), n, t, acc)
    }
}

/// A `tagcase` as statements: its value bound once, then a `match`.
pub fn put_tagcase(c: &'static Ctx, xs: Sexps, n: i64, t: &'static Tail, acc: Chars) -> Chars {
    let acc = put(str_lit("let tagcase_ = "), acc);
    let acc = put_exp(c, car(xs), n, value(), acc);
    let acc = put_nl(n, put(str_lit(";"), acc));
    let acc = put(str_lit("match *tagcase_ {"), acc);
    let acc = put_tagcase_arms(c, cdr(xs), i64_plus(n, 1i64), t, acc);
    put(str_lit("}"), put_nl(n, acc))
}

/// A lambda as a value: a closure, `move`, since what it captures is
/// `Copy`, made a `&'static dyn Fn` by `lambdaN`, `N` its arity.
pub fn put_lambda(c: &'static Ctx, e: &'static Sexp, params: Sexps, body: Sexps, n: i64, acc: Chars) -> Chars {
    let acc = put(str_lit("lambda"), acc);
    let acc = put(i64_to_string(size(params)), acc);
    let acc = put(str_lit("(move |"), acc);
    let acc = put_lambda_params(c, params, acc);
    let acc = put(str_lit("| "), acc);
    if fact_at_p(c, e, str_lit("fallible")) {
        put(str_lit(")"), put_block(with_locals(c, cons(str_lit("%fallible"), map(&param_name, params))), body, n, ok_value(), acc))
    } else {
        put(str_lit(")"), put_block(with_locals(c, cons(str_lit("%infallible"), map(&param_name, params))), body, n, value(), acc))
    }
}

/// `x`, or `(x T)` as `x: T`.
pub fn put_lambda_params(c: &'static Ctx, params: Sexps, acc: Chars) -> Chars {
    if null_p(params) {
        acc
    } else {
        let acc = {
            let tagcase_ = car(params);
            match *tagcase_ {
                Sexp::Lst(xt, src_file, src_line, src_pos) => {
                    put_type(c, second(xt), put(str_lit(": "), put(mangle(sym_name(car(xt))), acc)))
                }
                _ => {
                    let name = tagcase_;
                    put(mangle(sym_name(name)), acc)
                }
            }
        };
        put_lambda_params(c, cdr(params), if null_p(cdr(params)) {
            acc
        } else {
            put(str_lit(", "), acc)
        })
    }
}

/// A letrec's procedures, made through knots: each knot made, then each
/// closure, whose group it reaches through the knots, then each knot
/// tied; a statement a line.
pub fn put_letrec(c: &'static Ctx, bindings: Sexps, names: Strings, n: i64, acc: Chars) -> Chars {
    let inside = with_locals(c, map(lambda1(move |x: Str| {
        string_append(str_lit("%knot "), x)
    }), names));
    let acc = put_sep(lambda2(move |b: &'static Sexp, acc: Chars| {
        let ys = items(b);
        let acc = put(str_lit("let "), acc);
        let acc = put(mangle(sym_name(car(ys))), acc);
        let acc = put(str_lit("__knot = knot::<"), acc);
        let acc = put_type(c, second(ys), acc);
        put_nl(n, put(str_lit(">();"), acc))
    }), str_lit(""), bindings, acc);
    let acc = put_sep(lambda2(move |b: &'static Sexp, acc: Chars| {
        let ys = items(b);
        let acc = put(str_lit("let "), acc);
        let acc = put(mangle(sym_name(car(ys))), acc);
        let acc = put(str_lit(" = "), acc);
        let acc = put_exp(inside, third(ys), n, value(), acc);
        put_nl(n, put(str_lit(";"), acc))
    }), str_lit(""), bindings, acc);
    put_sep(lambda2(move |x: Str, acc: Chars| {
        put_nl(n, put(str_lit(");"), put(mangle(x), put(str_lit("__knot.set("), put(mangle(x), acc)))))
    }), str_lit(""), names, acc)
}

pub fn put_list(c: &'static Ctx, xs: Sexps, n: i64, acc: Chars) -> Chars {
    if null_p(xs) {
        put(str_lit("nil()"), acc)
    } else {
        let acc = put(str_lit("cons("), acc);
        let acc = put_exp(c, car(xs), n, value(), acc);
        let acc = put(str_lit(", "), acc);
        let acc = put_list(c, cdr(xs), n, acc);
        put(str_lit(")"), acc)
    }
}

/// `e` is the whole form, `h` its head's name and `xs` the rest.
pub fn put_form(c: &'static Ctx, e: &'static Sexp, h: Str, xs: Sexps, n: i64, t: &'static Tail, acc: Chars) -> Chars {
    if string_eq_p(h, str_lit("if")) {
        let acc = put(str_lit("if "), acc);
        let acc = put_exp(c, car(xs), n, value(), acc);
        let acc = put(str_lit(" "), acc);
        let acc = put_block(c, cons(second(xs), nil()), n, t, acc);
        let acc = put(str_lit(" else "), acc);
        put_block(c, cons(third(xs), nil()), n, t, acc)
    } else if string_eq_p(h, str_lit("cond")) {
        put_cond(c, xs, n, t, acc)
    } else if string_eq_p(h, str_lit("and")) {
        if null_p(xs) {
            put(str_lit("true"), acc)
        } else {
            put(str_lit(")"), put_joined(c, xs, str_lit(" && "), n, put(str_lit("("), acc)))
        }
    } else if string_eq_p(h, str_lit("or")) {
        if null_p(xs) {
            put(str_lit("false"), acc)
        } else {
            put(str_lit(")"), put_joined(c, xs, str_lit(" || "), n, put(str_lit("("), acc)))
        }
    } else if (string_eq_p(h, str_lit("with")) && null_p(cdr(cdr(xs)))) {
        // A `with` of one expression, no block: only its names are its.
        put_exp(with_opened(c, e), second(xs), n, opened_tail(c, e, t), acc)
    } else if (string_eq_p(h, str_lit("begin")) || string_eq_p(h, str_lit("let")) || string_eq_p(h, str_lit("let*")) || string_eq_p(h, str_lit("tagcase")) || string_eq_p(h, str_lit("with"))) {
        put_block(c, cons(e, nil()), n, t, acc)
    } else if string_eq_p(h, str_lit("case")) {
        let acc = put(str_lit("match "), acc);
        let acc = put_exp(c, car(xs), n, value(), acc);
        let acc = put(str_lit(" {"), acc);
        let acc = put_case_arms(c, cdr(xs), i64_plus(n, 1i64), t, acc);
        put(str_lit("}"), put_nl(n, acc))
    } else if string_eq_p(h, str_lit("lambda")) {
        put_lambda(c, e, items(car(xs)), cdr(xs), n, acc)
    } else if string_eq_p(h, str_lit("list")) {
        put_list(c, xs, n, acc)
    } else if string_eq_p(h, str_lit("the")) {
        // `the::<T>(e)`: the type said to rustc too, which may need it where
        // FX-26's checker did (a tag's payload, a list nothing else types).
        let acc = put(str_lit("the::<"), acc);
        let acc = put_type(c, car(xs), acc);
        let acc = put(str_lit(">("), acc);
        let acc = put_exp(c, second(xs), n, value(), acc);
        put(str_lit(")"), acc)
    } else if (string_eq_p(h, str_lit("letrec")) || string_eq_p(h, str_lit("letregion"))) {
        put_block(c, cons(e, nil()), n, t, acc)
    } else if abort_p(c, e) {
        let acc = put(str_lit("return Err(unwind("), acc);
        let acc = put_joined(c, xs, str_lit(", "), n, acc);
        put(str_lit("))"), acc)
    } else if (string_eq_p(h, str_lit("prompt")) && string_eq_p(local_kind(h, ctx_locals(c)), str_lit(""))) {
        put_prompt(c, e, xs, n, acc)
    } else if null_p(xs) {
        put_question(c, e, put(str_lit("()"), put(callee(c, h), acc)))
    } else {
        put_question(c, e, put(str_lit(")"), put_joined(c, xs, str_lit(", "), n, put(str_lit("("), put(callee(c, h), acc)))))
    }
}

/// `(prompt tag body handler)`: the body run in a closure that returns a
/// `Result`, and its abort to the tag handled; any other abort passed on,
/// if the function written may abort, else none can come (the checker
/// found the prompt contains every abort its body may make).
pub fn put_prompt(c: &'static Ctx, e: &'static Sexp, xs: Sexps, n: i64, acc: Chars) -> Chars {
    let inner = with_locals(c, cons(str_lit("%fallible"), nil()));
    let acc = put_nl(i64_plus(n, 1i64), put(str_lit("{"), acc));
    let acc = put(str_lit("let prompt_tag__ = "), acc);
    let acc = put_exp(c, car(xs), i64_plus(n, 1i64), value(), acc);
    let acc = put_nl(i64_plus(n, 1i64), put(str_lit(";"), acc));
    let acc = put(str_lit("match (move || -> Result<_, Unwind> "), acc);
    let acc = put_block(inner, cons(second(xs), nil()), i64_plus(n, 1i64), ok_value(), acc);
    let acc = put(str_lit(")() {"), acc);
    let acc = put_nl(i64_plus(n, 2i64), acc);
    let acc = put(str_lit("Ok(v) => v,"), acc);
    let acc = put_nl(i64_plus(n, 2i64), acc);
    let acc = put(str_lit("Err(u) if u.is(prompt_tag__) => ("), acc);
    let acc = put_exp(c, third(xs), i64_plus(n, 2i64), value(), acc);
    let acc = put(str_lit(")(prompt_tag__.payload(u)),"), acc);
    let acc = put_nl(i64_plus(n, 2i64), acc);
    let acc = put(if (fact_at_p(c, e, str_lit("contains")) || not(fallible_here_p(c))) {
        str_lit("Err(u) => unreachable_unwind(u),")
    } else {
        str_lit("Err(u) => return Err(u),")
    }, acc);
    let acc = put_nl(i64_plus(n, 1i64), acc);
    let acc = put(str_lit("}"), acc);
    put(str_lit("}"), put_nl(n, acc))
}

/// A call the checker found may abort takes a `?`.
pub fn put_question(c: &'static Ctx, e: &'static Sexp, acc: Chars) -> Chars {
    if fact_at_p(c, e, str_lit("fallible-call")) {
        put(str_lit("?"), acc)
    } else {
        acc
    }
}

// Top-level forms
/// Parameters, from a lambda's names and its `subr` type's; `mut` if
/// `mutable`, for a procedure that loops.
pub fn put_params(c: &'static Ctx, names: Sexps, types: Sexps, mutable: bool, acc: Chars) -> Chars {
    if null_p(names) {
        acc
    } else {
        let name = {
            let tagcase_ = car(names);
            match *tagcase_ {
                Sexp::Lst(xs, src_file, src_line, src_pos) => {
                    car(xs)
                }
                _ => {
                    let other = tagcase_;
                    other
                }
            }
        };
        let acc = if mutable {
            put(str_lit("mut "), acc)
        } else {
            acc
        };
        let acc = put(mangle(sym_name(name)), acc);
        let acc = put(str_lit(": "), acc);
        let acc = put_type(c, car(types), acc);
        put_params(c, cdr(names), cdr(types), mutable, if null_p(cdr(names)) {
            acc
        } else {
            put(str_lit(", "), acc)
        })
    }
}

/// A poly's binders as a fn's generics: a type is a Rust type parameter,
/// `Copy` and `'static` as every KFX value is; an effect is erased, and so,
/// until places come (TODO.md section 14), is a region, every one's place
/// being the heap.
pub fn put_generics(mut binders: Sexps, mut first: bool, mut acc: Chars) -> Chars {
    loop {
        if null_p(binders) {
            if first {
                return acc;
            } else {
                return put(str_lit(">"), acc);
            }
        } else {
            let b = items(car(binders));
            let kind = sym_name(second(b));
            if string_eq_p(kind, str_lit("type")) {
                let acc = put(if first {
                    str_lit("<")
                } else {
                    str_lit(", ")
                }, acc);
                let acc = put(camel(sym_name(car(b))), acc);
                return put_generics(cdr(binders), false, put(str_lit(": Copy + 'static"), acc));
            } else if (string_eq_p(kind, str_lit("effect")) || string_eq_p(kind, str_lit("region"))) {
                binders = cdr(binders);
                continue;
            } else {
                return error(string_append(str_lit("kfx: KFX-0 has no poly over a "), kind));
            }
        }
    }
}

/// A poly type's body, or a plambda's: what is under the binders.
pub fn unpoly(e: &'static Sexp) -> &'static Sexp {
    if (head_is_p(e, str_lit("poly")) || head_is_p(e, str_lit("plambda"))) {
        third(items(e))
    } else {
        e
    }
}

pub fn put_define(c: &'static Ctx, name: &'static Sexp, r#type: &'static Sexp, defined: &'static Sexp, acc: Chars) -> Chars {
    let binders = if head_is_p(r#type, str_lit("poly")) {
        items(second(items(r#type)))
    } else {
        nil()
    };
    let r#type = unpoly(r#type);
    let defined = unpoly(defined);
    let lambda_p = head_is_p(defined, str_lit("lambda"));
    let body = if lambda_p {
        cdr(cdr(items(defined)))
    } else {
        the::<Sexps>(cons(defined, nil()))
    };
    let doc_p = (comment_p(car(body)) && not(null_p(cdr(body))));
    let acc = if doc_p {
        put(str_lit("\n"), put_comment(string_chars(comment_text(car(body))), str_lit("///"), 0i64, true, acc))
    } else {
        acc
    };
    let body = if doc_p {
        cdr(body)
    } else {
        body
    };
    let fallible = (lambda_p && fallible_effect_p(c, second(items(r#type))));
    let t = if lambda_p {
        returns(sym_name(name), map(&param_name, items(second(items(defined)))), true, fallible)
    } else {
        value()
    };
    let loops_p = (lambda_p && tail_calls_p(t, last(body)));
    let inner = if lambda_p {
        with_locals(c, cons(if fallible {
            str_lit("%fallible")
        } else {
            str_lit("%infallible")
        }, map(&param_name, items(second(items(defined))))))
    } else {
        c
    };
    let acc = put(str_lit("pub fn "), acc);
    let acc = put(mangle(sym_name(name)), acc);
    let acc = put_generics(binders, true, acc);
    let acc = if lambda_p {
        let acc = put(str_lit("("), acc);
        let acc = put_params(c, items(second(items(defined))), items(third(items(r#type))), loops_p, acc);
        let acc = put(str_lit(") -> "), acc);
        if fallible {
            put(str_lit(", Unwind>"), put_type(c, fourth(items(r#type)), put(str_lit("Result<"), acc)))
        } else {
            put_type(c, fourth(items(r#type)), acc)
        }
    } else {
        put_type(c, r#type, put(str_lit("() -> "), acc))
    };
    let acc = put(str_lit(" {"), acc);
    if loops_p {
        let acc = put_nl(2i64, put(str_lit("loop {"), put_nl(1i64, acc)));
        let acc = put_stmts(inner, body, 2i64, t, acc);
        put(str_lit("\n    }\n}\n\n"), acc)
    } else {
        put(str_lit("\n}\n\n"), put_stmts(inner, body, 1i64, if fallible {
            ok_value()
        } else {
            value()
        }, put_nl(1i64, acc)))
    }
}

pub fn put_rec(mut c: &'static Ctx, mut bindings: Sexps, mut acc: Chars) -> Chars {
    loop {
        if null_p(bindings) {
            return acc;
        } else {
            let b = items(car(bindings));
            (bindings, acc) = (cdr(bindings), put_define(c, car(b), second(b), third(b), acc));
            continue;
        }
    }
}

pub fn put_variants(c: &'static Ctx, variants: Sexps, acc: Chars) -> Chars {
    if null_p(variants) {
        acc
    } else {
        let v = items(car(variants));
        let acc = put(str_lit("    "), acc);
        let acc = put(camel(sym_name(car(v))), acc);
        let acc = put(str_lit("("), acc);
        let acc = put_types(c, cdr(v), acc);
        put_variants(c, cdr(variants), put(str_lit("),\n"), acc))
    }
}

/// Fields `f0`, `f1`, ..., from `i`, with their types if `typed`.
pub fn put_fields(c: &'static Ctx, types: Sexps, i: i64, typed: bool, acc: Chars) -> Chars {
    if null_p(types) {
        acc
    } else {
        let acc = if i64_eq(i, 0i64) {
            acc
        } else {
            put(str_lit(", "), acc)
        };
        let acc = put(str_lit("f"), acc);
        let acc = put(i64_to_string(i), acc);
        let acc = if typed {
            put_type(c, car(types), put(str_lit(": "), acc))
        } else {
            acc
        };
        put_fields(c, cdr(types), i64_plus(i, 1i64), typed, acc)
    }
}

pub fn put_constructors(c: &'static Ctx, d: Str, params: Strings, variants: Sexps, acc: Chars) -> Chars {
    if null_p(variants) {
        acc
    } else {
        let v = items(car(variants));
        let tag = sym_name(car(v));
        let acc = put(str_lit("pub fn "), acc);
        let acc = put(mangle(tag), acc);
        let acc = put_generics_of(params, true, acc);
        let acc = put(str_lit("("), acc);
        let acc = put_fields(c, cdr(v), 0i64, true, acc);
        let acc = put(str_lit(") -> &'static "), acc);
        let acc = put(camel(d), acc);
        let acc = put_generics_of(params, false, acc);
        let acc = put(str_lit(" {\n    alloc("), acc);
        let acc = put(camel(d), acc);
        let acc = put(str_lit("::"), acc);
        let acc = put(camel(tag), acc);
        let acc = put(str_lit("("), acc);
        let acc = put_fields(c, cdr(v), 0i64, false, acc);
        put_constructors(c, d, params, cdr(variants), put(str_lit("))\n}\n\n"), acc))
    }
}

/// An enum, generic in its type parameters (its regions are erased), and a
/// constructor for each variant.
pub fn put_datatype(c: &'static Ctx, xs: Sexps, acc: Chars) -> Chars {
    let d = type_head_name(car(xs));
    let params = head_type_params(car(xs));
    let acc = put(str_lit("pub enum "), acc);
    let acc = put(camel(d), acc);
    let acc = put_generics_of(params, true, acc);
    let acc = put(str_lit(" {\n"), acc);
    let acc = put_variants(c, cdr(xs), acc);
    let acc = put(str_lit("}\n\n"), acc);
    put_constructors(c, d, params, cdr(xs), acc)
}

/// A generative type: a new type, a newtype in Rust, and its conversions.
pub fn put_generative(c: &'static Ctx, xs: Sexps, acc: Chars) -> Chars {
    let t = type_head_name(car(xs));
    let params = head_type_params(car(xs));
    let inside = not(string_eq_p(module_here(c), str_lit("")));
    let acc = put(str_lit("#[derive(Clone, Copy)]\npub struct "), acc);
    let acc = put(camel(t), acc);
    let acc = put_generics_of(params, true, acc);
    let acc = put(if inside {
        str_lit("(")
    } else {
        str_lit("(pub ")
    }, acc);
    let acc = put_type(c, second(xs), acc);
    let acc = put(if inside {
        str_lit(");\n\nfn up_")
    } else {
        str_lit(");\n\npub fn up_")
    }, acc);
    let acc = put(mangle(t), acc);
    let acc = put_generics_of(params, true, acc);
    let acc = put(str_lit("(x: "), acc);
    let acc = put_type(c, second(xs), acc);
    let acc = put(str_lit(") -> "), acc);
    let acc = put(camel(t), acc);
    let acc = put_generics_of(params, false, acc);
    let acc = put(str_lit(" {\n    "), acc);
    let acc = put(camel(t), acc);
    let acc = put(if inside {
        str_lit("(x)\n}\n\nfn down_")
    } else {
        str_lit("(x)\n}\n\npub fn down_")
    }, acc);
    let acc = put(mangle(t), acc);
    let acc = put_generics_of(params, true, acc);
    let acc = put(str_lit("(x: "), acc);
    let acc = put(camel(t), acc);
    let acc = put_generics_of(params, false, acc);
    let acc = put(str_lit(") -> "), acc);
    let acc = put_type(c, second(xs), acc);
    put(str_lit(" {\n    x.0\n}\n\n"), acc)
}

/// Lines, each not empty four spaces in: `acc`, a module's items.
pub fn indented(mut cs: Chars, mut start: bool, mut acc: Chars) -> Chars {
    loop {
        if null_p(cs) {
            return acc;
        } else if char_eq_p(car(cs), '\n') {
            (cs, start, acc) = (cdr(cs), true, cons(car(cs), acc));
            continue;
        } else if start {
            (cs, start, acc) = (cdr(cs), false, cons(car(cs), put(str_lit("    "), acc)));
            continue;
        } else {
            (cs, start, acc) = (cdr(cs), false, cons(car(cs), acc));
            continue;
        }
    }
}

/// Written text, its last newlines dropped.
pub fn trimmed(mut cs: Chars) -> Chars {
    loop {
        if (not(null_p(cs)) && char_eq_p(car(cs), '\n')) {
            cs = cdr(cs);
            continue;
        } else {
            return cs;
        }
    }
}

pub fn without(mut xs: Strings, mut ys: Strings) -> Strings {
    loop {
        if null_p(xs) {
            return nil();
        } else {
            if string_member_p(car(xs), ys) {
                xs = cdr(xs);
                continue;
            } else {
                return cons(car(xs), without(cdr(xs), ys));
            }
        }
    }
}

pub fn definition_p(e: &'static Sexp) -> bool {
    (head_is_p(e, str_lit("define")) || head_is_p(e, str_lit("define*")) || head_is_p(e, str_lit("define-rec")) || module_def_p(e) || head_is_p(e, str_lit("define-datatype")) || head_is_p(e, str_lit("define-type")) || head_is_p(e, str_lit("define-generative")))
}

// A program's top-level expressions, for running Fixpt's programs as Rust
// (`kfx --toplevel`, scripts/run-fixpt-programs.py): a `Show` for each
// datatype, writing a value as Fixpt does, `#<sum TAG>`; and
// `kfx_toplevel`, which writes each top-level expression's value on a line,
// top-level strings too, as `fixpt eval` does.
pub fn put_show_arms(d: Str, variants: Sexps, acc: Chars) -> Chars {
    if null_p(variants) {
        acc
    } else {
        let tag = sym_name(car(items(car(variants))));
        let acc = put(str_lit("            "), acc);
        let acc = put(camel(d), acc);
        let acc = put(str_lit("::"), acc);
        let acc = put(camel(tag), acc);
        let acc = put(str_lit("(..) => out.push_str(str_lit(\"#<sum "), acc);
        let acc = put(tag, acc);
        put_show_arms(d, cdr(variants), put(str_lit(">\").as_str()),\n"), acc))
    }
}

pub fn put_show_impls(mut forms: Sexps, mut acc: Chars) -> Chars {
    loop {
        if null_p(forms) {
            return acc;
        } else if head_is_p(car(forms), str_lit("define-datatype")) {
            let xs = cdr(items(car(forms)));
            let d = type_head_name(car(xs));
            let params = head_type_params(car(xs));
            let acc = put(str_lit("impl"), acc);
            let acc = put_generics_of(params, true, acc);
            let acc = put(str_lit(" Show for "), acc);
            let acc = put(camel(d), acc);
            let acc = put_generics_of(params, false, acc);
            let acc = put(str_lit(" {\n    fn show(&self, out: &mut String) {\n        match self {\n"), acc);
            let acc = put_show_arms(d, cdr(xs), acc);
            return put_show_impls(cdr(forms), put(str_lit("        }\n    }\n}\n\n"), acc));
        } else if head_is_p(car(forms), str_lit("define-generative")) {
            let h = second(items(car(forms)));
            let params = head_type_params(h);
            let acc = put(str_lit("impl"), acc);
            let acc = if null_p(params) {
                acc
            } else {
                put(str_lit(">"), put_sep(lambda2(move |n: Str, acc: Chars| {
                    put(str_lit(": Copy + 'static + Show"), put(camel(n), acc))
                }), str_lit(", "), params, put(str_lit("<"), acc)))
            };
            let acc = put(str_lit(" Show for "), acc);
            let acc = put(camel(type_head_name(h)), acc);
            let acc = put_generics_of(params, false, acc);
            return put_show_impls(cdr(forms), put(str_lit(" {\n    fn show(&self, out: &mut String) {\n        self.0.show(out)\n    }\n}\n\n"), acc));
        } else {
            forms = cdr(forms);
            continue;
        }
    }
}

/// In toplevel mode, a module's datatypes' and generative types' `Show`,
/// inside it, where their representations are seen.
pub fn put_show_generatives(forms: Sexps, acc: Chars) -> Chars {
    put_show_impls(concat(map(lambda1(move |f: &'static Sexp| {
        if (head_is_p(f, str_lit("define-generative")) || head_is_p(f, str_lit("define-datatype"))) {
            the::<Sexps>(cons(f, nil()))
        } else {
            nil()
        }
    }), forms)), acc)
}

pub fn put_top(c: &'static Ctx, form: &'static Sexp, acc: Chars) -> Chars {
    let xs = items(form);
    let h = sym_name(car(xs));
    if string_eq_p(h, str_lit("define-effect")) {
        acc
    } else if string_eq_p(h, str_lit("define-type")) {
        let acc = put(str_lit("pub type "), acc);
        let acc = put(camel(type_head_name(second(xs))), acc);
        let acc = put_generics_of(head_type_params(second(xs)), false, acc);
        let acc = put(str_lit(" = "), acc);
        let acc = put_type(c, third(xs), acc);
        put(str_lit(";\n\n"), acc)
    } else if string_eq_p(h, str_lit("define-datatype")) {
        put_datatype(c, cdr(xs), acc)
    } else if string_eq_p(h, str_lit("define-generative")) {
        put_generative(c, cdr(xs), acc)
    } else if module_def_p(form) {
        put_module(c, sym_name(second(xs)), cdr(items(third(xs))), acc)
    } else if (string_eq_p(h, str_lit("define")) || string_eq_p(h, str_lit("define*"))) {
        if i64_eq(size(xs), 4i64) {
            put_define(c, second(xs), third(xs), fourth(xs), acc)
        } else {
            put_define(c, second(xs), car(ctx_typed(c, sym_name(second(xs)))), third(xs), acc)
        }
    } else if string_eq_p(h, str_lit("define-rec")) {
        put_rec(c, cdr(xs), acc)
    } else {
        acc
    }
}

/// A module, a Rust `mod` (C19): its items as a program's, the program's
/// names in scope, its own hiding them.
pub fn put_module(c: &'static Ctx, m: Str, forms: Sexps, acc: Chars) -> Chars {
    let outer = {
        let tagcase_ = c;
        match *tagcase_ {
            Ctx::Ctx(ds, ts, ks, ls, xs, fs, ms, es, mods) => {
                ctx(ds, ts, without(ks, item_values(forms)), ls, xs, fs, ms, es, mods)
            }
        }
    };
    let inner = with_locals(collect(forms, outer), cons(string_append(str_lit("%in "), m), nil()));
    let body = put_tops(inner, forms, nil());
    let body = if string_member_p(str_lit("%toplevel"), ctx_locals(c)) {
        put_show_generatives(forms, body)
    } else {
        body
    };
    let acc = put(str_lit("pub mod "), acc);
    let acc = put(mangle(m), acc);
    let acc = put(str_lit(" {\n    use super::*;\n\n"), acc);
    put(str_lit("\n}\n\n"), indented(rev_onto(trimmed(body), nil()), true, acc))
}

/// A string at the top level is a comment. A procedure's documentation is
/// a string first in its body, as a Lisp docstring is: see `put-define`.
pub fn put_tops(mut c: &'static Ctx, mut forms: Sexps, mut acc: Chars) -> Chars {
    loop {
        if null_p(forms) {
            return acc;
        } else if comment_p(car(forms)) {
            let doc = (not(null_p(cdr(forms))) && definition_p(second(forms)));
            let acc = put_comment(string_chars(comment_text(car(forms))), str_lit("//"), 0i64, true, acc);
            return put_tops(c, cdr(forms), put(if doc {
                str_lit("\n")
            } else {
                str_lit("\n\n")
            }, acc));
        } else {
            (forms, acc) = (cdr(forms), put_top(c, car(forms), acc));
            continue;
        }
    }
}

pub fn toplevel_form_p(f: &'static Sexp) -> bool {
    not((definition_p(f) || head_is_p(f, str_lit("define-effect"))))
}

pub fn put_toplevel_lines(mut c: &'static Ctx, mut forms: Sexps, mut acc: Chars) -> Chars {
    loop {
        if null_p(forms) {
            return acc;
        } else if toplevel_form_p(car(forms)) {
            let acc = put(str_lit("    show_line(&mut out, (|| -> Result<_, Unwind> { Ok("), acc);
            let acc = put_exp(with_locals(c, cons(str_lit("%fallible"), nil())), car(forms), 1i64, value(), acc);
            return put_toplevel_lines(c, cdr(forms), put(str_lit(") })().unwrap_or_else(|u| unreachable_unwind(u)));\n"), acc));
        } else {
            forms = cdr(forms);
            continue;
        }
    }
}

pub fn put_toplevel(c: &'static Ctx, forms: Sexps, acc: Chars) -> Chars {
    let acc = put_show_impls(forms, acc);
    let acc = put(str_lit("/// The program's top-level expressions' values, as Fixpt writes them.\npub fn kfx_toplevel() -> Str {\n    let mut out = String::new();\n"), acc);
    let acc = put_toplevel_lines(c, forms, acc);
    put(str_lit("    shown(out)\n}\n"), acc)
}

